import { z } from "zod";

/**
 * Schema used by Gemini structured output.
 *
 * Gemini's current structured-output path does not accept
 * the nullable JSON Schema generated by Zod for these fields.
 */
export const codingEvaluationLlmSchema = z.object({
  timeComplexity: z.string().min(1),

  spaceComplexity: z.string().min(1),

  codeQualityScore: z
    .number()
    .min(0)
    .max(100),

  summary: z.string().min(1),

  suggestions: z.array(z.string().min(1)),
});

/**
 * Application-level schema.
 *
 * Null is still allowed here because the original evaluator
 * contract supports unknown/unavailable evaluation values.
 */
export const codingEvaluationSchema = z.object({
  timeComplexity: z.string().nullable(),

  spaceComplexity: z.string().nullable(),

  codeQualityScore: z
    .number()
    .min(0)
    .max(100)
    .nullable(),

  summary: z.string().nullable(),

  suggestions: z.array(z.string().min(1)),
});

export const codingEvaluationJsonSchema =
  z.toJSONSchema(codingEvaluationSchema);